    events: [
      { y: 1900, m: 1, tag: '史实', title: '1900 年的纽约', desc: '五个行政区刚刚合并两年，约 340 万人住在这座城市。高架铁路和电车早已不够用，第一条地铁由你来修。' },
      { y: 1900, m: 3, tag: '史实', title: '史实背景：第一条地铁开工', desc: '工人在百老汇和公园大道底下挖开隧道。本局的地铁由你规划，真实线路不会自动出现。' },
      { y: 1903, m: 12, tag: '史实', title: '威廉斯堡大桥通车', desc: '东河上第二座大桥通车，下东区的居民开始搬到布鲁克林。' },
      { y: 1904, m: 10, tag: '史实', title: '史实背景：纽约地铁通车', desc: '市政厅到 145 街的线路通车，第一天就有十多万人搭乘，票价 5 美分。' },
      { y: 1905, m: 10, tag: '史实', title: '市营史泰登岛渡轮开航', desc: '纽约市接管渡轮，把史泰登岛和下曼哈顿连接起来。', fx: { sat: { v: 0.3, months: 12 } } },
      { y: 1907, m: 10, tag: '史实', title: '1907 年恐慌', desc: '尼克博克信托公司挤兑引发金融恐慌，华尔街资金枯竭，私营公司的投资急剧收缩。' },
      { y: 1908, m: 2, tag: '史实', title: '哈德逊河底的管道通车', desc: '哈德逊与曼哈顿铁路开通，新泽西的通勤者第一次不用坐渡轮就能到曼哈顿。' },
      { y: 1909, m: 3, tag: '史实', title: '皇后区大桥通车', desc: '皇后区第一次有桥连接曼哈顿，同年曼哈顿大桥也投入使用，长岛市迅速工业化。' },
      { y: 1910, m: 11, tag: '史实', title: '宾夕法尼亚车站启用', desc: '宾夕法尼亚铁路穿过哈德逊河，把列车直接开进曼哈顿中城。', task: { id: 'ny-e1', type: 'facShare', fac: 'ny_penn', target: 0.2, months: 48, rewardMonths: 1, title: '宾夕法尼亚车站接驳', desc: '宾夕法尼亚铁路的列车穿过哈德逊河底直达曼哈顿中城。让到发旅客坐地铁接驳的比例达到 20%。' } },
      { y: 1911, m: 3, tag: '史实', title: '三角内衣厂大火', desc: '大火造成 146 名工人死亡，大多是移民女工，推动了全美的劳工立法。', fx: { sat: { v: -0.5, months: 6 } } },
      { y: 1913, m: 2, tag: '史实', title: '大中央总站落成', desc: '新的大中央总站启用，地下两层共 67 条轨道，周边的公园大道迅速成为高档地段。', task: { id: 'ny-e2', type: 'facShare', fac: 'ny_gct_f', target: 0.2, months: 48, rewardMonths: 1, title: '大中央总站接驳', desc: '新的大中央总站落成，北郊通勤列车全部改用电力。让到发旅客坐地铁接驳的比例达到 20%。' } },
      { y: 1913, m: 3, tag: '史实', title: '双重合约签订', desc: '纽约市与两家私营公司签订合约，投入约 3.4 亿美元，地铁一路修进皇后区、布朗克斯和布鲁克林南部。' },
      { y: 1916, m: 7, tag: '史实', title: '全美第一部区划条例', desc: '摩天楼的阴影引发争议，纽约规定高楼要逐层退缩，形成了后来的“婚礼蛋糕”式天际线。' },
      { y: 1917, m: 4, tag: '史实', title: '美国参战', desc: '纽约港成为向欧洲运送士兵和物资的主要港口，民用建设放缓。', fx: { demand: { sh: 0.95, lz: 0.9, months: 18 } } },
      { y: 1918, m: 10, tag: '史实', title: '大流感', desc: '流感在纽约夺走约 3 万人的生命，市政府错峰上下班以缓解地铁拥挤。', fx: { demand: { sh: 0.85, lz: 0.75, months: 3 } } },
      { y: 1924, m: 5, tag: '史实', title: '移民法收紧', desc: '国会大幅削减移民配额，埃利斯岛的高峰结束，城市人口增长放缓。' },
      { y: 1927, m: 11, tag: '史实', title: '荷兰隧道通车', desc: '世界上第一条机械通风的水下车行隧道连接了曼哈顿和新泽西。' },
      { y: 1929, m: 10, tag: '史实', title: '股市崩盘', desc: '黑色星期二之后，华尔街陷入恐慌，大萧条开始。', fx: { sat: { v: -1, months: 18 } } },
      { y: 1931, m: 10, tag: '史实', title: '乔治·华盛顿大桥通车', desc: '当时世界上跨度最大的吊桥把曼哈顿北端和新泽西连接起来。' },
      { y: 1932, m: 9, tag: '史实', title: '第八大道地铁通车', desc: '市营的独立地铁系统第一条线通车，和两家私营公司展开竞争。' },
      { y: 1936, m: 7, tag: '史实', title: '三区大桥通车', desc: '罗伯特·摩西建成连接曼哈顿、布朗克斯和皇后区的三区大桥，纽约进入汽车时代。' },
      { y: 1940, m: 6, tag: '史实', title: '地铁统一为市营', desc: '纽约市收购两家私营地铁公司，三大系统合并，第九大道高架随即停运，第二大道高架到 1942 年全线停运。' },
      { y: 1941, m: 12, tag: '史实', title: '美国参战', desc: '布鲁克林造船厂三班倒开工，纽约港成为大西洋战场的后勤基地。' },
      { y: 1946, m: 12, tag: '史实', title: '地铁客运量创纪录', desc: '当年地铁运送约 20 亿人次，是历史最高纪录。' },
      { y: 1948, m: 7, tag: '史实', title: '票价涨到 10 美分', desc: '维持了 44 年的 5 美分票价结束，地铁客流开始长期下降。' },
      { y: 1955, m: 5, tag: '史实', title: '第三大道高架停运', desc: '曼哈顿最后一条高架铁路停运，随后拆除，东区的地价开始上涨。' },
      { y: 1963, m: 10, tag: '史实', title: '宾夕法尼亚车站旧站房拆除', desc: '巨大的车站大厅被拆除，舆论哗然，促成了 1965 年的地标保护法。' },
      { y: 1964, m: 4, tag: '史实', title: '第二届世博会开幕', desc: '世博会第二次回到法拉盛草地，大地球仪成了皇后区的象征。', fx: { demand: { lz: 1.05, months: 12 } } },
      { y: 1964, m: 11, tag: '史实', title: '韦拉扎诺海峡大桥通车', desc: '史泰登岛第一次有桥连接布鲁克林，岛上开始快速发展。' },
      { y: 1966, m: 1, tag: '史实', title: '公交大罢工', desc: '地铁和公交工人罢工 12 天，全城瘫痪。', fx: { sat: { v: -1, months: 3 } } },
      { y: 1973, m: 4, tag: '史实', title: '世界贸易中心落成', desc: '双塔落成，成为当时世界上最高的建筑。' },
      { y: 1980, m: 4, tag: '史实', title: '公交大罢工', desc: '地铁和公交工人再次罢工 11 天，市民步行过桥上班。', fx: { sat: { v: -1, months: 3 } } },
      { y: 1984, m: 5, tag: '史实', title: '地铁“清洁车”计划', desc: '大都会运输署开始逐列清除涂鸦，到 1989 年最后一列涂鸦列车退役。' },
      { y: 1987, m: 10, tag: '史实', title: '黑色星期一', desc: '道琼斯指数一天下跌 22.6%，华尔街的扩张戛然而止。' },
      { y: 1997, m: 7, tag: '史实', title: '免费换乘', desc: '都会卡实现地铁与公交免费换乘，通勤成本明显下降。' },
      { y: 2015, m: 9, tag: '史实', title: '7 号线延伸到哈德逊园区', desc: '这是纽约地铁 25 年来第一次延伸，直接带动了西区的开发。' },
      { y: 2017, m: 1, tag: '史实', title: '第二大道线一期通车', desc: '规划了近一个世纪的第二大道地铁终于通车第一段。' },
      { y: 2020, m: 3, tag: '史实', title: '新冠疫情', desc: '纽约成为美国疫情的中心，地铁客流一度下降九成以上。', fx: { demand: { sc: 0.4, sh: 0.6, lz: 0.5, months: 6 } } },
    ],
